.ds-game-button {
  position: relative;
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 9px 19px;
  background: linear-gradient(#fff8e7, #e8d9b9);
  color: #24364c;
  border: 1px solid #c8b183;
  border-radius: 5px 22px 5px 22px;
  text-decoration: none;
  font-family: var(--font-display, 'Newsreader Variable', Georgia, serif);
  font-size: 18px;
  font-weight: 500;
  line-height: 1.2;
  box-shadow:
    inset 0 0 0 3px #fff9eb70,
    0 4px 12px #02091526;
  transition:
    translate 0.24s var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
    box-shadow 0.24s var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
    background 0.24s var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
}
.ds-game-button::after {
  content: '';
  position: absolute;
  inset: 4px;
  border: 1px solid #a38c5f65;
  border-radius: inherit;
  pointer-events: none;
}
.ds-game-button:hover {
  translate: 0 -2px;
  box-shadow:
    inset 0 0 0 3px #fff9ebc0,
    0 6px 18px #02091536;
}
.ds-game-button:active {
  translate: 0 1px;
}
.ds-action-arrow {
  width: 17px;
  height: 17px;
  margin-left: auto;
  transition: translate 0.24s var(--ease, cubic-bezier(0.22, 1, 0.36, 1));
}
.ds-game-button:hover .ds-action-arrow {
  translate: 3px 0;
}.ds-game-button:focus-visible { outline:2px solid #e7c477; outline-offset:5px; }@media(prefers-reduced-motion:reduce){.ds-game-button,.ds-action-arrow{transition:none}}

