.ds-dossier {
  position: relative;
  isolation: isolate;
  color: var(--ink, #25354b);
  background: linear-gradient(115deg, #f8f2e6, #eae2d1);
  border: 1px solid #c4ad81;
  border-radius: 15px 5px 15px 5px;
  padding: 30px;
  box-shadow: 0 14px 44px #040b1726;
}
.ds-dossier::before {
  content: '';
  position: absolute;
  inset: 7px;
  pointer-events: none;
  border: 1px solid #b5a28280;
  border-radius: 9px 3px 9px 3px;
}
.ds-dossier-content {
  position: relative;
  z-index: 1;
}.ds-dossier{font-family:var(--font-body, 'Source Sans 3 Variable', sans-serif);font-size:17px;line-height:1.5}.ds-dossier h2{font-family:var(--font-display, 'Newsreader Variable', Georgia, serif);font-size:32px;font-weight:550;line-height:1.12;margin:0 0 14px}.ds-dossier p{margin:0}
.ds-panel-corner {
  position: absolute;
  width: 43px;
  height: 43px;
  color: #a58b5d;
  fill: none;
  stroke: currentColor;
  stroke-width: 0.8;
  pointer-events: none;
}
.ds-corner-tl {
  top: 2px;
  left: 2px;
}
.ds-corner-tr {
  top: 2px;
  right: 2px;
  rotate: 90deg;
}
.ds-corner-bl {
  bottom: 2px;
  left: 2px;
  rotate: -90deg;
}
.ds-corner-br {
  bottom: 2px;
  right: 2px;
  rotate: 180deg;
}

.ds-archive-project-list a {
  display: inline-block;
  padding: 8px 12px;
  border: 1px solid #a5906666;
  border-radius: 3px;
  font-size: 16px;
  text-decoration: none;
  transition:
    background 0.2s,
    translate 0.2s;
}
.ds-archive-project-list a[aria-current='true'],
.ds-archive-project-list a:hover {
  background: #243b50;
  color: #fff1d8;
  translate: 0 -1px;
}.ds-archive-project-list{color:var(--ink, #25354b);font-family:var(--font-body, 'Source Sans 3 Variable', sans-serif);line-height:1.5}.ds-archive-project-list a:focus-visible { outline:2px solid #e7c477; outline-offset:5px; }

.ds-nav-item {
  position: relative;
  min-width: 70px;
  min-height: 65px;
  padding: 0 8px 12px;
  color: #d2cfca;
  text-decoration: none;
  font-family: var(--font-display, 'Newsreader Variable', Georgia, serif);
  font-size: 17px;
  transition:
    translate 0.2s var(--ease, cubic-bezier(0.22, 1, 0.36, 1)),
    color 0.2s;
}
.ds-nav-item .ds-celestial-icon {
  width: 27px;
  height: 27px;
}
.ds-nav-item[aria-current='page'] {
  color: #fff4d7;
}
.ds-nav-item[aria-current='page'] .ds-celestial-icon {
  filter: drop-shadow(0 1px 5px #d5b96c80);
}
.ds-nav-active {
  position: absolute;
  left: 50%;
  bottom: 2px;
  width: 5px;
  height: 5px;
  background: #f4ddb0;
  rotate: 45deg;
  opacity: 0;
}
.ds-nav-item[aria-current='page'] .ds-nav-active {
  opacity: 1;
}
.ds-nav-item[aria-current='page']::after {
  content: '';
  position: absolute;
  bottom: 4px;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, #d4b788, transparent);
}
.ds-nav-item:hover {
  color: #fff5dc;
  translate: 0 -2px;
}.ds-main-nav{display:flex;gap:34px;background:var(--color-midnight,#0c1829);padding:16px}.ds-nav-item{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px}.ds-nav-item:focus-visible { outline:2px solid #e7c477; outline-offset:5px; }@media(prefers-reduced-motion:reduce){.ds-nav-item{transition:none}}
